{
  "name": "terminal-browser",
  "version": "0.0.2",
  "description": "A browser running directly inside claude code. Preview websites, view HTML documents, and let your agent control the built in browser.",
  "author": {
    "name": "zenbu-labs"
  },
  "homepage": "https://github.com/zenbu-labs/terminal-browser/tree/main/claude-code-plugin",
  "repository": "https://github.com/zenbu-labs/terminal-browser",
  "license": "MIT",
  "keywords": [
    "browser",
    "function-hooks"
  ],
  "types": "./hooks/browser.d.ts",
  "userConfig": {
    "agentTool": {
      "type": "boolean",
      "title": "Give the agent a tool to open/close terminal-browser inside claude code",
      "description": "Adds an open/close tool the model can call to show a page in the browser pane. Off by default.",
      "default": false
    }
  }
}
